import{_ as s,o as a,c as n,ai as e}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"01 · 方法论与总体架构","description":"","frontmatter":{},"headers":[],"relativePath":"ai/sop/01-methodology.md","filePath":"ai/sop/01-methodology.md"}'),d={name:"ai/sop/01-methodology.md"};function l(r,t,p,i,o,h){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_01-·-方法论与总体架构" tabindex="-1">01 · 方法论与总体架构 <a class="header-anchor" href="#_01-·-方法论与总体架构" aria-label="Permalink to “01 · 方法论与总体架构”">​</a></h1><blockquote><p>先分清「方法」「工具」「项目事实」三层，再谈协作。这一章是后面七章的地基，也是整套 SOP 里唯一不随工具版本变化的部分。</p></blockquote><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>用 AI 写代码半年后，最容易攒下这四个毛病：</p><ul><li><strong>每次开新会话都要重新解释一遍</strong>：JDK 几、分层怎么走、哪个包不能动、构建命令是什么。解释成本比自己改还高。</li><li><strong>换工具就作废</strong>：花两周攒的 Rules、Skills、Agent 配置，从 Cursor 换到另一个工具时几乎全要重写，于是开始怀疑之前那两周是不是白干了。</li><li><strong>&quot;已完成&quot;没有定义</strong>：AI 说做完了，你问测试跑了吗，它说&quot;已补充测试&quot;；上线一跑才发现边界条件漏了。没有人能说清&quot;做完&quot;到底指什么。</li><li><strong>规则越写越长，越长越没人遵守</strong>：技术栈、目录约定、业务流程、安全红线、本次任务需求，全塞进一份规则文件。最后连你自己都不看，AI 更是只挑最后几行执行。</li></ul><p>这四个问题的根子是同一件事：<strong>把工具配置当成了方法，把规则当成了流程，把一次性的对话当成了项目资产。</strong></p><p>SOP 要解决的不是&quot;怎么让 AI 写更多代码&quot;，而是&quot;怎么让一个项目在被 AI 参与之后，仍然可理解、可复现、可验收&quot;。</p><h2 id="一、为什么需要一套-sop" tabindex="-1">一、为什么需要一套 SOP <a class="header-anchor" href="#一、为什么需要一套-sop" aria-label="Permalink to “一、为什么需要一套 SOP”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统软件开发</th><th>随手用 AI 辅助</th><th>SOP 化的 AI 开发</th></tr></thead><tbody><tr><td>上下文在哪</td><td>人脑 + 文档</td><td>单轮对话，会话结束即丢</td><td>仓库里的项目认知报告 + 规则文件</td></tr><tr><td>谁做决策</td><td>人</td><td>常常是 AI 顺手替你定了</td><td>需求、架构、验收由人拍板，有书面依据</td></tr><tr><td>产出物</td><td>代码 + 文档</td><td>代码 + 一段聊天记录</td><td>代码 + Spec + 验收记录 + 沉淀项</td></tr><tr><td>典型失败</td><td>需求理解偏差</td><td>改崩了看不懂 diff、越聊越乱</td><td>流程被跳过，能定位到是哪一步没做</td></tr><tr><td>换工具成本</td><td>低</td><td>高（配置全绑在工具上）</td><td>低（换的只是适配层）</td></tr><tr><td>可复现性</td><td>靠规范</td><td>靠运气</td><td>靠输入、输出、验收三件套</td></tr></tbody></table><p>一句话：AI 把<strong>执行</strong>变得极便宜，于是<strong>定义问题</strong>和<strong>判断结果</strong>成了瓶颈。SOP 就是把这两件事固化下来。</p><div class="tip custom-block"><p class="custom-block-title">核心原则</p><p>学习和理解是基础，项目实践是验证，通用方法论是最终沉淀。不能为了追求自动化，牺牲开发者对业务、架构和代码的理解。</p></div><h2 id="二、五条原则" tabindex="-1">二、五条原则 <a class="header-anchor" href="#二、五条原则" aria-label="Permalink to “二、五条原则”">​</a></h2><ol><li><strong>理解和判断在人，执行在 AI。</strong> 需求取舍、架构决策、验收判定不出让。AI 可以列选项、写草稿、跑检查，但不替你拍板。</li><li><strong>通用优先，工具适配分离。</strong> 方法论不能长在某个工具的目录结构上；目录名、配置语法、调用方式全部下沉到适配层。</li><li><strong>新项目和老项目分入口，汇合到同一条主链。</strong> 新项目先定边界再建体系，老项目先扫描理解再逐步接入；进了开发阶段，两者走同一套流程。</li><li><strong>前期最小必备，过程中按需补充。</strong> 不要求开工前把 Rules、Agents、Skills 全部配齐。过度设计比缺配置更常见。</li><li><strong>完成以证据为准。</strong> 编译、测试、diff、验收清单是可核验的证据；&quot;AI 声称完成&quot;不是。</li></ol><h2 id="三、总体架构-三层" tabindex="-1">三、总体架构：三层 <a class="header-anchor" href="#三、总体架构-三层" aria-label="Permalink to “三、总体架构：三层”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ 通用方法层 ─ 跨项目、跨工具、长期不变 ──────────────────┐</span></span>
<span class="line"><span>│ 项目认知 · 需求分析 · 架构设计 · 任务拆解                 │</span></span>
<span class="line"><span>│ Rules 设计 · Agent 职责 · Skill 设计 · 测试验收 · 复盘沉淀  │</span></span>
<span class="line"><span>└──────────────────────┬─────────────────────────────────┘</span></span>
<span class="line"><span>                       │ 适配（工具版本变了只改这一层）</span></span>
<span class="line"><span>┌──────────────────────▼─────────────────────────────────┐</span></span>
<span class="line"><span>│ 工具适配层 ─ 以对应版本官方文档为准                      │</span></span>
<span class="line"><span>│ Cursor / WorkBuddy / Claude Code / 其他支持 Agent 的工具  │</span></span>
<span class="line"><span>│ 只负责：目录名、配置语法、调用方式、能力边界              │</span></span>
<span class="line"><span>└──────────────────────┬─────────────────────────────────┘</span></span>
<span class="line"><span>                       │ 落地到具体仓库</span></span>
<span class="line"><span>┌──────────────────────▼─────────────────────────────────┐</span></span>
<span class="line"><span>│ 项目特定层 ─ 只属于这一个仓库                            │</span></span>
<span class="line"><span>│ 业务规则 · 数据表 · 接口契约 · 历史决策 · gotchas          │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>一条判断准则：<strong>如果一段内容换一个 AI 编程工具就得重写，那它写错了层。</strong></p><p>这也是本 SOP 不叫《Cursor 使用教程》的原因。Cursor、WorkBuddy、Claude Code 只是执行工具，工具特性以各自官方文档为准，本 SOP 不把某个工具的目录结构当成行业通用规范。涉及具体配置的落地办法放在 <a href="./index.html">M3 的工具适配指南</a>（建设中），不在方法论章节里混写。</p><h2 id="四、五个协作机制-各管一件事" tabindex="-1">四、五个协作机制，各管一件事 <a class="header-anchor" href="#四、五个协作机制-各管一件事" aria-label="Permalink to “四、五个协作机制，各管一件事”">​</a></h2><p>这是最容易混淆的地方，也是整套体系的支点。</p><table tabindex="0"><thead><tr><th>机制</th><th>回答什么问题</th><th>约束/作用于</th><th>生命周期</th><th>粒度</th><th>不负责</th></tr></thead><tbody><tr><td><strong>Rules</strong></td><td>所有任务必须遵守什么</td><td>AI 的行为边界</td><td>长期，随项目迭代</td><td>全局 / 项目 / 目录级</td><td>本次任务要做什么</td></tr><tr><td><strong>Agent</strong></td><td>谁来做、按什么职责做</td><td>执行角色</td><td>按阶段启用</td><td>一个角色</td><td>定规则、写规范</td></tr><tr><td><strong>Skills</strong></td><td>重复出现的方法怎么复用</td><td>可复用流程</td><td>跨项目积累，跟人走</td><td>一个方法</td><td>存业务事实</td></tr><tr><td><strong>MCP</strong></td><td>需要接哪些外部能力/数据</td><td>连接边界</td><td>按需接入</td><td>一个外部系统</td><td>决定开发流程</td></tr><tr><td><strong>Hooks</strong></td><td>哪些检查必须确定性执行</td><td>自动化脚本</td><td>长期</td><td>一条检查</td><td>判断业务对错</td></tr></tbody></table><p>一句话记住：</p><blockquote><p><strong>Rules 负责约束，Agent 负责角色与任务执行，Skills 负责可复用的方法，MCP 负责外部能力连接，Hooks 负责确定性自动化。</strong></p></blockquote><p>职责混淆自查表 —— 这些是真实项目里最常见的错放：</p><table tabindex="0"><thead><tr><th>常见写法</th><th>问题</th><th>应该放哪</th></tr></thead><tbody><tr><td>Rules 里写「本次给工单列表加 status 过滤」</td><td>规则管所有任务，这条只管一次</td><td>Spec / 任务文档</td></tr><tr><td>Rules 里写整套业务流程说明</td><td>规则会膨胀到没人读</td><td>项目认知报告</td></tr><tr><td>把客户业务表、字段含义写进 Skill</td><td>跟人走的 Skill 会污染下一个项目</td><td>项目特定层</td></tr><tr><td>让 Reviewer Agent 自己决定「这样可以合」</td><td>执行者不能当验收人</td><td>人的验收环节</td></tr><tr><td>靠 Prompt 提醒「别提交密钥」</td><td>提醒会被上下文稀释</td><td>Hooks 做确定性拦截</td></tr><tr><td>一开始就接五六个 MCP 数据源</td><td>没验证过需要，只增加排障面</td><td>按需，接入前先过三项检查</td></tr></tbody></table><h2 id="五、人与-ai-的职责边界" tabindex="-1">五、人与 AI 的职责边界 <a class="header-anchor" href="#五、人与-ai-的职责边界" aria-label="Permalink to “五、人与 AI 的职责边界”">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>人（拍板）</th><th>AI（执行）</th><th>留下的证据</th></tr></thead><tbody><tr><td>需求取舍</td><td>定做什么、不做什么</td><td>提澄清问题、列模糊点</td><td>需求澄清记录</td></tr><tr><td>架构设计</td><td>定模块边界、技术栈、系统级约束</td><td>列备选方案与代价</td><td>技术设计文档</td></tr><tr><td>业务规则</td><td>确认规则来源与例外</td><td>从代码/文档里抽取候选</td><td>规则清单 + 来源</td></tr><tr><td>代码实现</td><td>审方案、砍 scope、看 diff</td><td>按 Spec 实现</td><td>小步提交 + diff</td></tr><tr><td>测试用例</td><td>定验收条件</td><td>补用例、跑命令</td><td>测试结果</td></tr><tr><td>质量验收</td><td>逐条对照清单判定</td><td>自查、提问题</td><td>验收报告</td></tr><tr><td>交付上线</td><td>决定合不合、什么时候发</td><td>汇总文档与变更</td><td>交付报告</td></tr></tbody></table><p>注意最后一行：<strong>AI 不负责宣布完成</strong>。这不是不信任模型，是责任没法外包 —— 出了线上问题，回滚和复盘的是人。</p><h2 id="六、完整工作流程图" tabindex="-1">六、完整工作流程图 <a class="header-anchor" href="#六、完整工作流程图" aria-label="Permalink to “六、完整工作流程图”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ 入口分叉 ]</span></span>
<span class="line"><span>新项目 ── 目标 / 范围 / 技术栈 / 目录 / 模块边界 ──┐</span></span>
<span class="line"><span>                                                  ├─→ 《项目认知报告》</span></span>
<span class="line"><span>老项目 ── 扫描 / 识别栈 / 理解架构 / 业务规则 / 债 ─┘          │</span></span>
<span class="line"><span>                                                              ▼</span></span>
<span class="line"><span>                                              [ 最小 AI 协作体系 ]</span></span>
<span class="line"><span>                                          全局 Rules + 一条开发主链</span></span>
<span class="line"><span>                                                              │</span></span>
<span class="line"><span>                                                              ▼</span></span>
<span class="line"><span>              ┌──────────── 标准开发主链（单次迭代）──────────────┐</span></span>
<span class="line"><span>              │ 需求澄清 → 技术设计 → 任务拆解 → 实现              │</span></span>
<span class="line"><span>              │     → 测试 / Review → 交付                        │</span></span>
<span class="line"><span>              │   （新项目与老项目在这里合流，步骤完全一致）        │</span></span>
<span class="line"><span>              └──────────────────────┬───────────────────────────┘</span></span>
<span class="line"><span>                                     ▼</span></span>
<span class="line"><span>                 [ 阶段性复盘 ] 发现重复问题 → 分析根因</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span>                        ┌────────────┼────────────┐</span></span>
<span class="line"><span>                        ▼            ▼            ▼</span></span>
<span class="line"><span>                   Rules / Agent / Skill / Docs / 脚本</span></span>
<span class="line"><span>                        └──── 复用验证 → 更新通用方法库 ────┘</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span>                                     └──→ 下一迭代回到主链</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>四阶段对应「项目初始化 → AI 协作体系 → 标准开发流程 → 持续改进」，八章内容都挂在这张图的某一段上，不会多出一条孤立流程。</p><h2 id="七、避免过度设计-什么时候才补" tabindex="-1">七、避免过度设计：什么时候才补 <a class="header-anchor" href="#七、避免过度设计-什么时候才补" aria-label="Permalink to “七、避免过度设计：什么时候才补”">​</a></h2><table tabindex="0"><thead><tr><th>时机</th><th>启动必备</th><th>明确不做</th></tr></thead><tbody><tr><td>项目启动</td><td>项目认知报告、全局 Rules（技术栈 / 禁改区 / 构建测试命令）、一条开发主链</td><td>全套 Agent、Skill 大全、接满 MCP</td></tr><tr><td>开发过程中</td><td>同类操作重复 3 次以上才建 Skill；确有并行收益才拆子 Agent</td><td>为展示多 Agent 而拆任务</td></tr><tr><td>阶段复盘</td><td>根因 → 判断沉淀位置 → 小范围复用验证</td><td>把所有经验一股脑写进 Rules</td></tr><tr><td>跨项目复用</td><td>通用方法库、模板库、版本记录</td><td>把项目业务事实带进通用库</td></tr></tbody></table><p>判断「值不值得沉淀」只需要三个问题：这个问题还会再出现吗？不沉淀的代价是什么？沉淀之后有没有第二个项目能验证它？三个都是肯定，才动手。</p><h2 id="八、本章输入-输出-验收标准" tabindex="-1">八、本章输入 / 输出 / 验收标准 <a class="header-anchor" href="#八、本章输入-输出-验收标准" aria-label="Permalink to “八、本章输入 / 输出 / 验收标准”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>一个准备引入 AI 协作的项目（新或老）；现有工具清单</td></tr><tr><td>输出</td><td>三层架构划分结论、五个机制的职责划分表、人/AI 分工表、本项目适用的流程图</td></tr><tr><td>验收</td><td>① 能说清哪些内容属于工具适配层；② 任取一条现有规则，能判断它是否放错了层；③ 能指出「完成」由谁判定、以什么为证据；④ 启动必备清单不超过 5 项</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">验收不通过的信号</p><p>如果讨论完还是「先把 Rules 写全再开工」，说明过度设计没挡住；如果所有内容都指向某一个工具的目录名，说明三层没分开。这两种情况都不要进入第 02 章。</p></div><h2 id="九、常见问题" tabindex="-1">九、常见问题 <a class="header-anchor" href="#九、常见问题" aria-label="Permalink to “九、常见问题”">​</a></h2><p><strong>Q：不配 Agent 也能叫 AI 协作体系吗？</strong> 能。单 Agent + 清晰 Rules + 一条主链，就是可用的最小体系。多 Agent 是任务并行度上来之后的结果，不是起点。</p><p><strong>Q：工具更新了，这套 SOP 会不会失效？</strong> 通用方法层不会。失效的只会是适配层的目录名和语法，改一处即可。这也是要求「具体配置以官方文档为准」的原因 —— 本文不写任何工具的目录结构。</p><p><strong>Q：Rules 和 Spec 有什么区别？</strong> Rules 管<strong>所有任务</strong>（不改 URL、不加依赖、分层约定）；Spec 管<strong>这一次任务</strong>（改什么、验收是什么、明确不做什么）。Spec 冻结后开发和 Review 都对着它，任务做完可以归档，但不要合并进 Rules。</p><p><strong>Q：小项目也要写项目认知报告吗？</strong> 要，但可以很短。哪怕只有技术栈、模块边界、构建命令、禁改区四行，也比每次会话重新解释强。老项目尤其不能省 —— 见第 02 章。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>三层架构：通用方法层 / 工具适配层 / 项目特定层；换工具只改中间那层。</li><li>五个机制各管一件事：Rules 约束、Agent 执行、Skills 复用方法、MCP 连外部、Hooks 做确定性检查。</li><li>新项目和老项目入口不同，但汇合到同一条标准开发主链。</li><li>人对需求、架构、验收负责；AI 对自己的「已完成」不负责判定。</li><li>启动只做最小必备，重复三次以上才沉淀，沉淀前先想清楚验证场景。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>这套 SOP 的价值不在于让 AI 写得更多，而在于让协作结果<strong>可复现、可验收、可迁移</strong>。先把三层分开，再把五个机制的职责钉死，后面七章都只是在这张图上填细节。做对这一步，换工具、换项目、换模型都不会让你从零开始。</p><hr><p>配套：<a href="/my-vitepress-site/ai/sop/">SOP 总览与阅读路径</a> · 下一章：<a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 项目接入与初始化</a> · 站内已有实践：<a href="/my-vitepress-site/ai/productivity/ai-coding-workflow.html">AI 辅助编程工作流</a></p>`,47)])])}const u=s(d,[["render",l]]);export{c as __pageData,u as default};
